const size_t app_js_len = 50099;

void bootstrapLittleFS() {
  String currentVersion = String(__DATE__) + " " + String(__TIME__);
  String fsVersion = "";
  if (LittleFS.exists("/version.txt")) {
    File vFile = LittleFS.open("/version.txt", "r");
    if (vFile) {
      fsVersion = vFile.readString();
      vFile.close();
    }
  }

  if (fsVersion != currentVersion) {
    Serial.println("Firmware updated! Overwriting LittleFS web files...");
    Serial.println("Writing /index.html...");
    File f_index_html = LittleFS.open("/index.html", "w");
    if (f_index_html) {
      f_index_html.write(index_html_data, index_html_len);
      f_index_html.close();
    }
    Serial.println("Writing /style.css...");
    File f_style_css = LittleFS.open("/style.css", "w");
    if (f_style_css) {
      f_style_css.write(style_css_data, style_css_len);
      f_style_css.close();
    }
    Serial.println("Writing /app.js...");
    File f_app_js = LittleFS.open("/app.js", "w");
    if (f_app_js) {
      f_app_js.write(app_js_data, app_js_len);
      f_app_js.close();
    }
    File vFile = LittleFS.open("/version.txt", "w");
    if (vFile) {
      vFile.print(currentVersion);
      vFile.close();
    }
    Serial.println("Web files updated successfully!");
  } else {
    Serial.println("Web files are up to date.");
  }
}
